package scheduler_test

import (
	"testing"

	"github.com/ai-verification/go-scheduler/internal/scheduler"
)

// --- Step 1: Basic CRUD ---

func TestCreateAndGet(t *testing.T) {
	s := scheduler.New()
	id := s.Create("send-email", 1)
	task, ok := s.Get(id)
	if !ok {
		t.Fatal("expected task to exist")
	}
	if task.Name != "send-email" {
		t.Fatalf("expected name send-email, got %q", task.Name)
	}
	if task.Status != scheduler.StatusPending {
		t.Fatalf("expected pending status, got %v", task.Status)
	}
}

func TestGetMissing(t *testing.T) {
	s := scheduler.New()
	_, ok := s.Get(999)
	if ok {
		t.Fatal("expected false for missing task")
	}
}

func TestListAll(t *testing.T) {
	s := scheduler.New()
	s.Create("a", 1)
	s.Create("b", 2)
	s.Create("c", 3)
	if s.Len() != 3 {
		t.Fatalf("expected 3 tasks, got %d", s.Len())
	}
}

// --- Step 2: Status transitions ---

func TestStartTask(t *testing.T) {
	s := scheduler.New()
	id := s.Create("job", 1)
	if err := s.Start(id); err != nil {
		t.Fatalf("Start failed: %v", err)
	}
	task, _ := s.Get(id)
	if task.Status != scheduler.StatusRunning {
		t.Fatalf("expected running, got %v", task.Status)
	}
}

func TestCompleteTask(t *testing.T) {
	s := scheduler.New()
	id := s.Create("job", 1)
	s.Start(id)
	if err := s.Complete(id); err != nil {
		t.Fatalf("Complete failed: %v", err)
	}
	task, _ := s.Get(id)
	if task.Status != scheduler.StatusDone {
		t.Fatalf("expected done, got %v", task.Status)
	}
}

func TestFailTask(t *testing.T) {
	s := scheduler.New()
	id := s.Create("job", 1)
	s.Start(id)
	if err := s.Fail(id); err != nil {
		t.Fatalf("Fail failed: %v", err)
	}
	task, _ := s.Get(id)
	if task.Status != scheduler.StatusFailed {
		t.Fatalf("expected failed, got %v", task.Status)
	}
}

func TestInvalidTransition(t *testing.T) {
	s := scheduler.New()
	id := s.Create("job", 1)
	// Cannot complete a pending task directly
	if err := s.Complete(id); err == nil {
		t.Fatal("expected error completing a pending task")
	}
}

// --- Step 3: Priority listing ---

func TestListByPriority(t *testing.T) {
	s := scheduler.New()
	s.Create("low", 1)
	s.Create("high", 10)
	s.Create("med", 5)
	tasks := s.ListByPriority()
	if len(tasks) != 3 {
		t.Fatalf("expected 3 tasks, got %d", len(tasks))
	}
	if tasks[0].Priority != 10 {
		t.Fatalf("expected highest priority first, got %d", tasks[0].Priority)
	}
	if tasks[2].Priority != 1 {
		t.Fatalf("expected lowest priority last, got %d", tasks[2].Priority)
	}
}

func TestFilterByStatus(t *testing.T) {
	s := scheduler.New()
	id1 := s.Create("a", 1)
	s.Create("b", 2)
	s.Start(id1)
	running := s.FilterByStatus(scheduler.StatusRunning)
	if len(running) != 1 {
		t.Fatalf("expected 1 running task, got %d", len(running))
	}
	pending := s.FilterByStatus(scheduler.StatusPending)
	if len(pending) != 1 {
		t.Fatalf("expected 1 pending task, got %d", len(pending))
	}
}
